350.   <script>
351.     const fields = [
352.       {
353.         id: "fullName",
354.         name: "fullName",
355.         label: "Full name",
356.         type: "text",
357.         autocomplete: "name",
358.         required: true,
359.         placeholder: "Jordan Lee",
360.         helpText: "",
361.         errorMessage: "Error: Enter your full name."
362.       },
363.       {
364.         id: "email",
365.         name: "email",
366.         label: "Email address",
367.         type: "email",
368.         autocomplete: "email",
369.         required: true,
370.         placeholder: "jordan@example.com",
371.         helpText: "",
372.         errorMessage: "Error: Enter a valid email address, like name@example.com."
373.       },
374.       {
375.         id: "phone",
376.         name: "phone",
377.         label: "Phone number",
378.         type: "tel",
379.         autocomplete: "tel",
380.         required: false,
381.         placeholder: "(555) 123-4567",
382.         helpText: "Optional. Use a format like (555) 123-4567 or +1 555 123 4567.",
383.         errorMessage: "Error: Enter a valid phone number in the expected format."
384.       }
385.     ];
386. 
387.     const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
388.     const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;
389. 
390.     const escapeHtml = (value) =>
391.       String(value)
392.         .replace(/&/g, "&amp;")
393.         .replace(/</g, "&lt;")
394.         .replace(/>/g, "&gt;")
395.         .replace(/"/g, "&quot;")
396.         .replace(/'/g, "&#39;");
397. 
398.     function App() {
399.       return `
400.         <main id="maincontent" tabindex="-1">
401.           <div class="page-shell">
402.             <section class="hero" aria-labelledby="support-heading">
403.               ${HeroCopy()}
404.               ${ContactFormCard()}
405.             </section>
406.           </div>
407.         </main>
408.       `;
409.     }
410. 
411.     function HeroCopy() {
412.       return `
413.         <div class="hero-copy">
414.           <div>
415.             <span class="eyebrow">Support team</span>
416.             <h1 id="support-heading">Get help from our product specialists</h1>
417.             <p class="lede">
418.               Share a few details and our support team will follow up with the right guidance for your setup,
419.               rollout, or account questions.
420.             </p>
421.           </div>
422.           <ul class="feature-list" aria-label="Support highlights">
423.             <li><strong>Fast triage</strong><p>Send the basics so we can route your request quickly.</p></li>
424.             <li><strong>Clear follow-up</strong><p>We will respond using the email address you provide.</p></li>
425.             <li><strong>Optional callback</strong><p>Add a phone number if you would like a call.</p></li>
426.           </ul>
427.         </div>
428.       `;
429.     }
430. 
431.     function ContactFormCard() {
432.       return `
433.         <section class="form-card" aria-labelledby="contact-form-title">
434.           <div class="form-header">
435.             <h2 id="contact-form-title">Contact support</h2>
436.             <p>Required fields are marked with <span aria-hidden="true">*</span>.</p>
437.             <p class="required-note">We will only use your contact details to respond to this request.</p>
438.           </div>
439.           <form id="contact-form" novalidate>
440.             ${fields.map(FormField).join("")}
441.             <div class="actions">
442.               <button class="submit-button" type="submit">Send request</button>
443.               <p id="form-status" class="status-message" role="status" aria-live="polite"></p>
444.             </div>
445.           </form>
446.         </section>
447.       `;
448.     }
449. 
450.     function FormField(field) {
451.       const helperId = field.helpText ? `${field.id}-help` : "";
452.       const errorId = `${field.id}-error`;
453.       const describedBy = [helperId, errorId].filter(Boolean).join(" ");
454. 
455.       return `
456.         <div class="form-field">
457.           <label class="field-label" for="${field.id}">
458.             ${escapeHtml(field.label)}
459.             ${field.required ? '<span class="required-mark" aria-hidden="true">*</span>' : '<span class="field-optional">(optional)</span>'}
460.           </label>
461.           <div class="input-shell">
462.             <input
463.               id="${field.id}"
464.               name="${field.name}"
465.               type="${field.type}"
466.               autocomplete="${field.autocomplete}"
467.               ${field.required ? "required" : ""}
468.               ${field.type === "tel" ? 'inputmode="tel"' : ""}
469.               placeholder="${escapeHtml(field.placeholder)}"
470.               aria-describedby="${describedBy}"
471.               aria-errormessage="${errorId}"
472.             >
473.           </div>
474.           ${field.helpText ? `<p class="field-help" id="${helperId}">${escapeHtml(field.helpText)}</p>` : ""}
475.           <p class="field-error" id="${errorId}" hidden></p>
476.         </div>
477.       `;
478.     }
479. 
480.     function getErrorMessage(field, value) {
481.       const trimmed = value.trim();
482. 
483.       if (field.required && !trimmed) {
484.         return field.errorMessage;
485.       }
486. 
487.       if (!trimmed && !field.required) {
488.         return "";
489.       }
490. 
491.       if (field.type === "email" && !emailPattern.test(trimmed)) {
492.         return field.errorMessage;
493.       }
494. 
495.       if (field.type === "tel" && !phonePattern.test(trimmed)) {
496.         return field.errorMessage;
497.       }
498. 
499.       return "";
500.     }
501. 
502.     function setFieldState(input, message) {
503.       const errorElement = document.getElementById(`${input.id}-error`);
504.       const hasError = Boolean(message);
505. 
506.       input.setAttribute("aria-invalid", String(hasError));
507.       errorElement.hidden = !hasError;
508.       errorElement.textContent = message;
509.     }
510. 
511.     function validateField(input) {
512.       const field = fields.find((entry) => entry.id === input.id);
513.       const message = getErrorMessage(field, input.value);
514.       setFieldState(input, message);
515.       return !message;
516.     }
517. 
518.     function wireForm() {
519.       const form = document.getElementById("contact-form");
520.       const status = document.getElementById("form-status");
521.       const inputs = Array.from(form.querySelectorAll("input"));
522. 
523.       inputs.forEach((input) => {
524.         input.addEventListener("blur", () => {
525.           validateField(input);
526.         });
527. 
528.         input.addEventListener("input", () => {
529.           const errorElement = document.getElementById(`${input.id}-error`);
530.           if (!errorElement.hidden) {
531.             validateField(input);
532.           }
533. 
534.           if (status.textContent) {
535.             status.textContent = "";
536.             status.className = "status-message";
537.           }
538.         });
539.       });
540. 
541.       form.addEventListener("submit", (event) => {
542.         event.preventDefault();
543. 
544.         const invalidInput = inputs.find((input) => !validateField(input));
545. 
546.         if (invalidInput) {
547.           status.textContent = "Please correct the highlighted fields and try again.";
548.           status.className = "status-message";
549.           invalidInput.focus();
550.           return;
551.         }
552. 
553.         status.textContent = "Your request is ready to send.";
554.         status.className = "status-message success";
555.       });
556.     }
557. 
558.     document.getElementById("app").innerHTML = App();
559.     wireForm();
560.   </script>
561. </body>
