       width: 100%;
       border: 1px solid rgba(148, 163, 184, 0.32);
       border-radius: var(--radius-md);
       padding: 0.95rem 1rem;
       font: inherit;
       color: var(--text);
       background: rgba(255, 255, 255, 0.84);
       transition: border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
     }

     @media (prefers-color-scheme: dark) {
       input {
         background: rgba(15, 23, 42, 0.78);
       }
     }

     input::placeholder {
       color: #64748b;
     }

     input:focus {
       outline: 3px solid transparent;
       border-color: var(--accent);
       box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.18);
     }

     .field-help,
     .field-error {
       margin: 0;
       font-size: 0.92rem;
     }

     .field-help {
       color: var(--muted);
     }

     .field-error {
       color: var(--error);
     }

     .field-error[hidden] {
       display: none;
     }

     input[aria-invalid="true"] {
       border-color: var(--error);
       background: var(--error-soft);
     }

     .actions {
       display: flex;
       align-items: center;
       gap: 1rem;
       flex-wrap: wrap;
       margin-top: 0.25rem;
     }

     .submit-button {
       appearance: none;
       border: 0;
       border-radius: 999px;
       padding: 0.95rem 1.4rem;
       font: inherit;
       font-weight: 700;
       color: white;
       background: linear-gradient(135deg, var(--accent), var(--accent-strong));
       box-shadow: 0 14px 30px rgba(37, 99, 235, 0.28);
       cursor: pointer;
       transition: transform 0.2s ease, box-shadow 0.2s ease;
     }

     .submit-button:hover {
       transform: translateY(-1px);
       box-shadow: 0 18px 32px rgba(37, 99, 235, 0.32);
     }

     .submit-button:focus-visible {
       outline: 3px solid transparent;
       box-shadow:
         0 0 0 4px rgba(37, 99, 235, 0.18),
         0 18px 32px rgba(37, 99, 235, 0.32);
     }

     .status-message {
       min-height: 1.5rem;
       margin: 0;
       font-weight: 600;
     }

     .status-message.success {
       color: var(--success);
     }

     @media (max-width: 860px) {
       .hero {
         grid-template-columns: 1fr;
       }

       .hero-copy,
       .form-card {
         padding: 1.5rem;
       }

       .feature-list {
         grid-template-columns: 1fr;
       }
     }

     @media (forced-colors: active) {
       .skip-link,
       .hero-copy,
       .form-card,
       input,
       .submit-button,
       .feature-list li {
         border: 1px solid CanvasText;
         box-shadow: none;
       }

       .submit-button {
         background: ButtonFace;
         color: ButtonText;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#maincontent">Skip to main content</a>
   <div id="app"></div>

   <script>
     const fields = [
       {
         id: "fullName",
         name: "fullName",
         label: "Full name",
         type: "text",
         autocomplete: "name",
         required: true,
         placeholder: "Jordan Lee",
         helpText: "",
         errorMessage: "Error: Enter your full name."
       },
       {
         id: "email",
         name: "email",
         label: "Email address",
         type: "email",
         autocomplete: "email",
         required: true,
         placeholder: "jordan@example.com",
         helpText: "",
         errorMessage: "Error: Enter a valid email address, like name@example.com."
       },
       {
         id: "phone",
         name: "phone",
         label: "Phone number",
         type: "tel",
         autocomplete: "tel",
         required: false,
         placeholder: "(555) 123-4567",
         helpText: "Optional. Use a format like (555) 123-4567 or +1 555 123 4567.",
         errorMessage: "Error: Enter a valid phone number in the expected format."
       }
     ];

     const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
     const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;

     const escapeHtml = (value) =>
       String(value)
         .replace(/&/g, "&amp;")
         .replace(/</g, "&lt;")
         .replace(/>/g, "&gt;")
         .replace(/"/g, "&quot;")
         .replace(/'/g, "&#39;");

     function App() {
       return `
         <main id="maincontent" tabindex="-1">
           <div class="page-shell">
             <section class="hero" aria-labelledby="support-heading">
               ${HeroCopy()}
               ${ContactFormCard()}
             </section>
           </div>
         </main>
       `;
     }

     function HeroCopy() {
       return `
         <div class="hero-copy">
           <div>
             <span class="eyebrow">Support team</span>
             <h1 id="support-heading">Get help from our product specialists</h1>
             <p class="lede">
               Share a few details and our support team will follow up with the right guidance for your setup,
               rollout, or account questions.
             </p>
           </div>
           <ul class="feature-list" aria-label="Support highlights">
             <li><strong>Fast triage</strong><p>Send the basics so we can route your request quickly.</p></li>
             <li><strong>Clear follow-up</strong><p>We will respond using the email address you provide.</p></li>
             <li><strong>Optional callback</strong><p>Add a phone number if you would like a call.</p></li>
           </ul>
         </div>
       `;
     }

     function ContactFormCard() {
       return `
         <section class="form-card" aria-labelledby="contact-form-title">
           <div class="form-header">
             <h2 id="contact-form-title">Contact support</h2>
             <p>Required fields are marked with <span aria-hidden="true">*</span>.</p>
             <p class="required-note">We will only use your contact details to respond to this request.</p>
           </div>
           <form id="contact-form" novalidate>
             ${fields.map(FormField).join("")}
             <div class="actions">
               <button class="submit-button" type="submit">Send request</button>
               <p id="form-status" class="status-message" role="status" aria-live="polite"></p>
             </div>
           </form>
         </section>
       `;
     }

     function FormField(field) {
       const helperId = field.helpText ? `${field.id}-help` : "";
       const errorId = `${field.id}-error`;
       const describedBy = [helperId, errorId].filter(Boolean).join(" ");

       return `
         <div class="form-field">
           <label class="field-label" for="${field.id}">
             ${escapeHtml(field.label)}
             ${field.required ? '<span class="required-mark" aria-hidden="true">*</span>' : '<span class="field-optional">(optional)</span>'}
           </label>
           <div class="input-shell">
             <input
               id="${field.id}"
               name="${field.name}"
               type="${field.type}"
               autocomplete="${field.autocomplete}"
               ${field.required ? "required" : ""}
               ${field.type === "tel" ? 'inputmode="tel"' : ""}
               placeholder="${escapeHtml(field.placeholder)}"
               aria-describedby="${describedBy}"
               aria-errormessage="${errorId}"
             >
           </div>
           ${field.helpText ? `<p class="field-help" id="${helperId}">${escapeHtml(field.helpText)}</p>` : ""}
           <p class="field-error" id="${errorId}" hidden></p>
         </div>
       `;
     }

     function getErrorMessage(field, value) {
       const trimmed = value.trim();

       if (field.required && !trimmed) {
         return field.errorMessage;
       }

       if (!trimmed && !field.required) {
         return "";
       }

       if (field.type === "email" && !emailPattern.test(trimmed)) {
         return field.errorMessage;
       }

       if (field.type === "tel" && !phonePattern.test(trimmed)) {
         return field.errorMessage;
       }

       return "";
     }

     function setFieldState(input, message) {
       const errorElement = document.getElementById(`${input.id}-error`);
       const hasError = Boolean(message);

       input.setAttribute("aria-invalid", String(hasError));
       errorElement.hidden = !hasError;
       errorElement.textContent = message;
     }

     function validateField(input) {
       const field = fields.find((entry) => entry.id === input.id);
       const message = getErrorMessage(field, input.value);
       setFieldState(input, message);
       return !message;
     }

     function wireForm() {
       const form = document.getElementById("contact-form");
       const status = document.getElementById("form-status");
       const inputs = Array.from(form.querySelectorAll("input"));

       inputs.forEach((input) => {
         input.addEventListener("blur", () => {
           validateField(input);
         });

         input.addEventListener("input", () => {
           const errorElement = document.getElementById(`${input.id}-error`);
           if (!errorElement.hidden) {
             validateField(input);
           }

           if (status.textContent) {
             status.textContent = "";
             status.className = "status-message";
           }
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         const invalidInput = inputs.find((input) => !validateField(input));

         if (invalidInput) {
           status.textContent = "Please correct the highlighted fields and try again.";
           status.className = "status-message";
           invalidInput.focus();
           return;
         }

         status.textContent = "Your request is ready to send.";
         status.className = "status-message success";
       });
     }

     document.getElementById("app").innerHTML = App();
     wireForm();
   </script>
 </body>
 </html>

')
